mapper.insert:
insert into asr_session (
    id, ws_session_id, member_id, start_time, status, created_at, updated_at
) values (
    #{id}, #{wsSessionId}, #{memberId}, #{startTime}, #{status}, #{createdAt}, #{updatedAt}
)

mapper.select:
select

from asr_session
where 1=1

    and member_id = #{memberId}


    and status = #{status}


    and source_lang = #{sourceLang}


    and target_lang = #{targetLang}

order by id desc
